mapper.select:
SELECT COUNT(*)
FROM ph_inv_flow
WHERE tenant_id = #{tenantId} AND biz_type = #{bizType} AND biz_no = #{bizNo}
  AND biz_line_id = #{bizLineId} AND batch_id = #{batchId} AND location_id = #{locationId}
  AND flow_type = #{flowType} AND deleted = 0

mapper.update:
UPDATE ph_inv_location_stock
SET qty = qty - #{qty}
WHERE batch_id = #{batchId} AND location_id = #{locationId} AND deleted = 0 AND qty >= #{qty}

UPDATE ph_inv_location_stock
SET qty = qty + #{qty}
WHERE batch_id = #{batchId} AND location_id = #{locationId} AND deleted = 0

mapper.insert:
INSERT INTO ph_inv_location_stock (batch_id, location_id, drug_id, qty, qty_frozen, creator, updater)
VALUES (#{batchId}, #{locationId}, #{drugId}, #{qty}, 0, 'system', 'system')
ON DUPLICATE KEY UPDATE qty = qty + #{qty}
